fn fibonacci(n: usize) -> Vec<i32> {
    // Since n is at least 2, we can initialize with the first two Fibonacci numbers
    let mut result = Vec::with_capacity(n);
    
    if n >= 1 {
        result.push(0);  // F(0)
    }
    
    if n >= 2 {
        result.push(1);  // F(1)
    }
    
    // Compute remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}